const L=(title,domains,objectives,sections,references,questions)=>({title,level:'ccp',domains,objectives,sections:sections.map(([title,body])=>({title,body})),references,read:sections.map(s=>s[1]).join('\n\n'),questions});
const R=(source,pages)=>({source,pages});
